WHERE dataprivacy_requests.id IN (
	SELECT
		dataprivacy_requests.id
	FROM dataprivacy_requests
	WHERE dataprivacy_requests.archived_at IS NULL
		AND dataprivacy_requests.status = sqlc.arg(current_status)
		AND dataprivacy_requests.expires_at IS NOT NULL
		AND dataprivacy_requests.expires_at <= sqlc.arg(expires_before)
	ORDER BY dataprivacy_requests.expires_at ASC, dataprivacy_requests.id ASC
	LIMIT COALESCE(sqlc.narg(result_limit), 50)
);

