	AND dataprivacy_requests.due_at <= sqlc.arg(due_before);

-- name: ReapRequests :execrows
DELETE FROM dataprivacy_requests
WHERE dataprivacy_requests.id IN (
	SELECT
		dataprivacy_requests.id
	FROM dataprivacy_requests
	WHERE dataprivacy_requests.artifact_ref = ''
		AND dataprivacy_requests.completed_at IS NOT NULL
		AND dataprivacy_requests.completed_at <= sqlc.arg(completed_before)
	ORDER BY dataprivacy_requests.completed_at ASC, dataprivacy_requests.id ASC
	LIMIT COALESCE(sqlc.narg(result_limit), 50)
);
